choose.when:
SELECT a.period_label AS periodLabel, f.field_name AS fieldName, SUM(d.numeric_value) AS total FROM report_submission_data d JOIN report_submissions s ON d.submission_id = s.id JOIN report_template_fields f ON f.id = d.field_id JOIN report_assignments a ON s.assignment_id = a.id INNER JOIN ( SELECT assignment_id, MAX(version) AS max_version FROM report_submissions WHERE status IN ('pending_receipt', 'received') GROUP BY assignment_id ) latest ON s.assignment_id = latest.assignment_id AND s.version = latest.max_version WHERE a.template_id = #{templateId} AND a.period_label IN
#{periodLabel}
AND s.status IN ('pending_receipt', 'received') AND f.field_type = 'number' AND f.data_type = 'summary' AND f.status = 'active' AND d.row_index = 0 GROUP BY a.period_label, f.field_name

mapper.update:
UPDATE report_aggregations
SET aggregated_data = #{aggregatedData},
    submitted_count = #{submittedCount},
    updated_at = CURRENT_TIMESTAMP(3)
WHERE template_id = #{templateId}
  AND assignment_id = #{assignmentId}
